"""Capture environment and library identities without accessing the GPU."""

import hashlib
import json
import os
from pathlib import Path
import shutil
import subprocess
import sys


def snapshot():
    names = ("PATH", "LD_LIBRARY_PATH", "CUDA_HOME", "CUDA_PATH",
             "CUDA_VISIBLE_DEVICES", "CUDA_MODULE_LOADING", "CUDA_FORCE_PTX_JIT",
             "CUDA_DISABLE_PTX_JIT", "CUDA_CACHE_DISABLE", "CUDA_CACHE_PATH")
    value = {"environment": {name: os.environ.get(name) for name in names}}
    value["tools"] = {}
    for name in ("nvcc", "ptxas"):
        path = Path(shutil.which(name))
        value["tools"][name] = {
            "path": str(path), "sha256": hashlib.sha256(path.read_bytes()).hexdigest(),
            "version": subprocess.check_output([str(path), "--version"], text=True),
        }
    value["cuda_links"] = {str(path): str(path.resolve())
                           for path in sorted(Path("/usr/local").glob("cuda*"))}
    driver = Path("/usr/lib/aarch64-linux-gnu/libcuda.so.1").resolve()
    value["driver"] = {"path": str(driver), "sha256": hashlib.sha256(
        driver.read_bytes()).hexdigest()}
    return value


if __name__ == "__main__":
    Path(sys.argv[1]).write_text(json.dumps(snapshot(), indent=2) + "\n")

"""Harvest single native F2FP encodings from controlled PTX variations."""
import hashlib
import json
import os
from pathlib import Path
import re
import struct
import subprocess

ROOT = Path(__file__).resolve().parent
TOOLS = ROOT.parent / "cuda134-qmul4-20261103/toolchain"
PTXAS = TOOLS / "cuda_nvcc-linux-sbsa-13.4.92-archive/bin/ptxas"
DISASM = TOOLS / "cuda_nvdisasm-linux-sbsa-13.4.92-archive/bin/nvdisasm"


def sha(blob):
    return hashlib.sha256(blob).hexdigest()


def text_section(blob):
    offset = struct.unpack_from("<Q", blob, 40)[0]
    size, count, index = struct.unpack_from("<HHH", blob, 58)
    headers = [struct.unpack_from("<IIQQQQIIQQ", blob, offset + i * size)
               for i in range(count)]
    head = headers[index]
    names = blob[head[4]:head[4]+head[5]]
    head = next(h for h in headers if names[h[0]:].split(b"\0", 1)[0] == b".text.Probe")
    return head[4], blob[head[4]:head[4]+head[5]]


def run(argv, stem):
    result = subprocess.run([str(a) for a in argv], text=True, capture_output=True,
                            timeout=60, env=dict(os.environ, TMPDIR=str(ROOT / "tmp")))
    path = ROOT / "preparation" / stem
    path.with_suffix(".command.json").write_text(json.dumps({
        "argv": [str(a) for a in argv], "returncode": result.returncode}, indent=2)+"\n")
    path.with_suffix(".stdout.txt").write_text(result.stdout)
    path.with_suffix(".stderr.txt").write_text(result.stderr)
    return result


PREFIX = """.version 9.4
.target sm_110a
.address_size 64
.visible .entry Probe(.param .u64 out, .param .u32 a, .param .u32 b) {
  .reg .b8 %b<4>;
  .reg .b16 %h<4>;
  .reg .b32 %r<8>;
  .reg .f32 %f<4>;
  .reg .b64 %rd;
  ld.param.u64 %rd, [out];
  ld.param.u32 %r1, [a];
  ld.param.u32 %r2, [b];
  cvt.u16.u32 %h0, %r1;
  cvt.u16.u32 %h1, %r2;
  mov.b16 {%b0, %b1}, %h0;
  mov.b32 %f0, %r1;
  mov.b32 %f1, %r2;
"""
SUFFIX = """
  st.global.u32 [%rd], %r3;
  st.global.u32 [%rd+4], %r1;
  st.global.u32 [%rd+8], %r2;
  ret;
}
"""


def main():
    variants = {}
    for source in ("e2m1", "e2m3", "e3m2", "e4m3", "e5m2"):
        src = "%b0" if source == "e2m1" else "%h0"
        variants["unpack_f16_"+source] = f"  cvt.rn.f16x2.{source}x2 %r3, {src};\n"
        variants["unpack_bf16_"+source] = f"  cvt.rn.bf16x2.{source}x2 %r3, {src};\n"
        variants["scaled_bf16_"+source] = (
            f"  cvt.rn.scaled::n2::ue8m0.bf16x2.{source}x2 %r3, {src}, %h1;\n")
        for src_fmt in ("f16", "bf16"):
            dest = "%b2" if source == "e2m1" else "%h2"
            extend = ("  mov.b16 %h2, {%b2, 0};\n" if source == "e2m1" else "")
            variants[f"pack_{source}_{src_fmt}"] = (
                f"  cvt.rn.satfinite.{source}x2.{src_fmt}x2 {dest}, %r1;\n" +
                extend + "  cvt.u32.u16 %r3, %h2;\n")
    variants["unpack_f16_e2m1_relu"] = "  cvt.rn.relu.f16x2.e2m1x2 %r3, %b0;\n"
    variants["scaled_bf16_e2m1_sat"] = (
        "  cvt.rn.satfinite.scaled::n2::ue8m0.bf16x2.e2m1x2 %r3, %b0, %h1;\n")
    variants["pack_e4m3_f16_relu"] = (
        "  cvt.rn.relu.satfinite.e4m3x2.f16x2 %h2, %r1;\n"
        "  cvt.u32.u16 %r3, %h2;\n")
    for dest in ("e4m3", "e5m2"):
        variants[f"pack_{dest}_f32"] = (
            f"  cvt.rn.satfinite.{dest}x2.f32 %h2, %f1, %f0;\n"
            "  cvt.u32.u16 %r3, %h2;\n")
    results = {}
    for name, body in variants.items():
        ptx = ROOT / "assembly" / (name+".ptx")
        ptx.write_text(PREFIX + body + SUFFIX)
        cubin = ptx.with_suffix(".cubin")
        compiled = run([PTXAS, "--verbose", "--gpu-name=sm_110a", "--output-file", cubin, ptx], name)
        item = {"PTX": body.strip(), "returncode": compiled.returncode}
        if compiled.returncode == 0:
            assert "warning" not in compiled.stderr.lower()
            dis = run([DISASM, "--print-code", "--print-instruction-encoding", cubin], name+"-sass")
            assert dis.returncode == 0 and not dis.stderr
            hits = re.findall(r"/\*([0-9a-f]+)\*/\s+(F2FP[^;]+);", dis.stdout)
            assert len(hits) == 1, (name, hits)
            offset, text = text_section(cubin.read_bytes())
            pc = int(hits[0][0], 16)
            raw = text[pc:pc+16]
            low, high = struct.unpack("<QQ", raw)
            item.update({"cubin_sha256": sha(cubin.read_bytes()), "text_file_offset": offset,
                         "instruction_offset": pc, "SASS": hits[0][1].strip(),
                         "encoding": raw.hex(), "low64": hex(low), "high64": hex(high)})
        results[name] = item
    (ROOT / "preparation/harvest.json").write_text(json.dumps(results, indent=2)+"\n")
    for name, item in results.items():
        print(name, item.get("SASS", "FAILED"), item.get("low64", ""), item.get("high64", ""))


if __name__ == "__main__":
    main()

"""Generate exact references for direct conversion and two scale encodings."""
from bisect import bisect_left
import json
import math
from pathlib import Path
import struct

ROOT = Path(__file__).resolve().parent
MAGS = (0, 0.5, 1, 1.5, 2, 3, 4, 6)


def fp4(code):
    return math.copysign(MAGS[code & 7], -1 if code & 8 else 1)


def fp8_units512(code):
    exponent, mantissa = (code & 127) >> 3, code & 7
    return mantissa if exponent == 0 else (8 + mantissa) << (exponent - 1)


LEVELS1024 = [2 * fp8_units512(c) for c in range(127)]
E5_LEVELS65536 = [(c & 3) if (c >> 2) == 0 else
                  (4 + (c & 3)) << ((c >> 2)-1) for c in range(124)]


def scaled_e4(a, s):
    product = (0,1,2,3,4,6,8,12)[a & 7] * fp8_units512(s)
    upper = bisect_left(LEVELS1024, product)
    if upper == 0:
        code = 0
    elif upper >= 127:
        code = 126
    else:
        dl, du = product-LEVELS1024[upper-1], LEVELS1024[upper]-product
        code = upper-1 if dl<du or (dl==du and (upper-1)%2==0) else upper
    return code | (((a & 8) << 4) ^ (s & 128))


def half(value):
    return struct.unpack("<H", struct.pack("<e", value))[0]


def scaled_e5(a, s):
    product = (0,1,2,3,4,6,8,12)[a & 7] * fp8_units512(s) * 64
    upper = bisect_left(E5_LEVELS65536, product)
    if upper == 0:
        code = 0
    elif upper >= 124:
        code = 123
    else:
        dl, du = product-E5_LEVELS65536[upper-1], E5_LEVELS65536[upper]-product
        code = upper-1 if dl<du or (dl==du and (upper-1)%2==0) else upper
    return code | (((a & 8) << 4) ^ (s & 128))


def bf16(value):
    bits = struct.unpack("<I", struct.pack("<f", value))[0]
    return (bits + 0x7fff + ((bits >> 16) & 1)) >> 16


def main():
    vectors = [(0x32,0x4040)]
    for scale in range(127):
        for pair in range(256):
            vectors.append((pair, scale | (scale << 8)))
    for pair in range(256):
        vectors.append((pair, pair % 127 | (((pair * 17 + 3) % 127) << 8)))
    e4_end = len(vectors)
    for scale in (121,123,125,127,128,129,131,135):
        for pair in range(256):
            vectors.append((pair, scale | (scale << 8)))
    for pair in range(256):
        vectors.append((pair, (121 + pair % 13) | ((121 + (pair * 7) % 13) << 8)))
    assert e4_end == 32769 and len(vectors) == 35073
    outputs = {name:[] for name in ("f16", "bf16_unity", "bf16_ue8m0", "direct_e4", "scaled_e4",
                                    "direct_e5", "scaled_e5")}
    for index,(pair,scales) in enumerate(vectors):
        cs = (pair & 15, pair >> 4)
        ss = (scales & 255, scales >> 8)
        values = [fp4(c) for c in cs]
        outputs["f16"].append(sum(half(v) << (16*i) for i,v in enumerate(values)))
        outputs["bf16_unity"].append(sum(bf16(v) << (16*i) for i,v in enumerate(values)))
        ue = [v * math.ldexp(1., s-127) for v,s in zip(values,ss)]
        outputs["bf16_ue8m0"].append(sum(bf16(v) << (16*i) for i,v in enumerate(ue)))
        outputs["direct_e4"].append(sum(scaled_e4(c,0x38) << (8*i) for i,c in enumerate(cs)))
        outputs["scaled_e4"].append(sum(scaled_e4(c,s) << (8*i) for i,(c,s) in enumerate(zip(cs,ss)))
                                  if index<e4_end else 0xffffffff)
        outputs["direct_e5"].append(sum(scaled_e5(c,0x38) << (8*i) for i,c in enumerate(cs)))
        outputs["scaled_e5"].append(sum(scaled_e5(c,s) << (8*i) for i,(c,s) in enumerate(zip(cs,ss)))
                                  if index<e4_end else 0xffffffff)
    (ROOT / "data/inputs.bin").write_bytes(b"".join(struct.pack("<II",*v) for v in vectors))
    for name,values in outputs.items():
        (ROOT / "data" / (name+".bin")).write_bytes(struct.pack("<"+"I"*len(values),*values))
    summary = {"vectors":len(vectors), "e4_scale_range":[0,e4_end],
               "ue8m0_control_range":[e4_end,len(vectors)],
               "e4_coverage":"all 256 FP4 pairs x all 127 nonnegative finite E4M3 equal-lane scales + 256 mixed-lane scales + smoke",
               "ue_coverage":"all 256 FP4 pairs x 8 UE8M0 exponents + 256 mixed-lane exponents",
               "first_input":vectors[0],"first_outputs":{k:hex(v[0]) for k,v in outputs.items()},
               "equivalence_domain":"finite nonnegative E4M3 scales; not NaN or arbitrary signed scales"}
    (ROOT / "preparation/oracle.json").write_text(json.dumps(summary,indent=2)+"\n")
    print(json.dumps(summary))


if __name__ == "__main__":
    main()

