#include <cuda.h>

#include <chrono>
#include <cstdint>
#include <cstdlib>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <iterator>
#include <string>
#include <thread>
#include <vector>

namespace {
const char* phase = "setup";

void Check(CUresult result, const char* api) {
  if (result == CUDA_SUCCESS) {
    std::cout << "{\"event\":\"cuda_success\",\"phase\":" << std::quoted(phase)
              << ",\"api\":" << std::quoted(api) << "}" << std::endl;
    return;
  }
  const char* name = "unknown";
  const char* description = "unknown";
  cuGetErrorName(result, &name);
  cuGetErrorString(result, &description);
  std::cout << "{\"event\":\"cuda_error\",\"phase\":" << std::quoted(phase)
            << ",\"api\":" << std::quoted(api) << ",\"code\":" << result
            << ",\"name\":" << std::quoted(name)
            << ",\"description\":" << std::quoted(description) << "}"
            << std::endl;
  std::_Exit(20);
}

std::vector<char> Read(const char* path) {
  std::ifstream file(path, std::ios::binary);
  return std::vector<char>((std::istreambuf_iterator<char>(file)), {});
}

void Save(const std::string& path, const char* data, size_t bytes) {
  std::ofstream file(path, std::ios::binary);
  file.write(data, static_cast<std::streamsize>(bytes));
  file.close();
  if (!file) std::_Exit(4);
}
}  // namespace

int main(int argc, char** argv) {
  if (argc != 4) return 2;
  const auto image = Read(argv[1]);
  const auto inputs = Read(argv[2]);
  const std::string prefix = argv[3];
  if (image.size() < 64 || inputs.empty() || inputs.size() % 8 != 0 ||
      inputs.size() > 1048576) return 2;
  const uint32_t count = inputs.size() / 8;
  const size_t bytes = count * sizeof(uint32_t);
  Check(cuInit(0), "cuInit");
  int driver = 0;
  Check(cuDriverGetVersion(&driver), "cuDriverGetVersion");
  CUdevice device;
  Check(cuDeviceGet(&device, 0), "cuDeviceGet");
  int major = 0;
  int minor = 0;
  Check(cuDeviceGetAttribute(&major,
                            CU_DEVICE_ATTRIBUTE_COMPUTE_CAPABILITY_MAJOR,
                            device), "cuDeviceGetAttribute-major");
  Check(cuDeviceGetAttribute(&minor,
                            CU_DEVICE_ATTRIBUTE_COMPUTE_CAPABILITY_MINOR,
                            device), "cuDeviceGetAttribute-minor");
  std::cout << "{\"event\":\"device\",\"major\":" << major
            << ",\"minor\":" << minor << ",\"driver_version\":" << driver
            << "}" << std::endl;
  if (major != 11 || minor != 0) return 3;
  CUcontext context;
  Check(cuCtxCreate(&context, nullptr, CU_CTX_SCHED_BLOCKING_SYNC, device),
        "cuCtxCreate");
  std::this_thread::sleep_for(std::chrono::milliseconds(1250));
  CUmodule module;
  Check(cuModuleLoadDataEx(&module, image.data(), 0, nullptr, nullptr),
        "cuModuleLoadDataEx");
  CUfunction function;
  Check(cuModuleGetFunction(&function, module, "Probe"), "cuModuleGetFunction");
  int binary = 0;
  Check(cuFuncGetAttribute(&binary, CU_FUNC_ATTRIBUTE_BINARY_VERSION, function),
        "cuFuncGetAttribute-binary");
  std::cout << "{\"event\":\"binary_version\",\"value\":" << binary << "}"
            << std::endl;
  if (binary != 110) return 3;
  CUdeviceptr input_ptr;
  CUdeviceptr allocation;
  Check(cuMemAlloc(&input_ptr, inputs.size()), "cuMemAlloc-inputs");
  Check(cuMemAlloc(&allocation, bytes + 32), "cuMemAlloc-outputs");
  CUdeviceptr output_ptr = allocation + 16;
  Check(cuMemcpyHtoD(input_ptr, inputs.data(), inputs.size()), "cuMemcpyHtoD");
  std::vector<char> output(bytes + 32, static_cast<char>(0xa5));
  Check(cuMemcpyHtoD(allocation, output.data(), output.size()), "cuMemcpyHtoD-guards");
  for (int step = 0; step < 2; ++step) {
    phase = step == 0 ? "smoke" : "matrix";
    uint32_t argument_count = step == 0 ? 1 : count;
    const uint32_t block = step == 0 ? 1 : 128;
    void* params[] = {&input_ptr, &output_ptr, &argument_count};
    Check(cuLaunchKernel(function, (argument_count + block - 1) / block,
                         1, 1, block, 1, 1, 0, nullptr, params, nullptr),
          "cuLaunchKernel");
    Check(cuCtxSynchronize(), "cuCtxSynchronize");
    Check(cuMemcpyDtoH(output.data(), allocation, output.size()), "cuMemcpyDtoH");
    bool guards_ok = true;
    for (int i = 0; i < 16; ++i) {
      guards_ok = guards_ok && output[i] == static_cast<char>(0xa5) &&
                  output[16 + bytes + i] == static_cast<char>(0xa5);
    }
    std::cout << "{\"event\":\"result\",\"phase\":" << std::quoted(phase)
              << ",\"vectors\":" << argument_count << ",\"guards_ok\":"
              << (guards_ok ? "true" : "false") << "}" << std::endl;
    if (step == 0) Save(prefix + ".smoke.bin", output.data() + 16, 4);
    if (step == 1) Save(prefix + ".actual.bin", output.data(), output.size());
    if (!guards_ok) return 30;
  }
  phase = "cleanup";
  Check(cuMemFree(input_ptr), "cuMemFree-inputs");
  Check(cuMemFree(allocation), "cuMemFree-outputs");
  Check(cuModuleUnload(module), "cuModuleUnload");
  Check(cuCtxDestroy(context), "cuCtxDestroy");
  std::cout << "{\"event\":\"completed\",\"vectors\":" << count << "}"
            << std::endl;
  return 0;
}

