"""Seal the complete experiment without placing executable artifacts in Git."""
import base64
import hashlib
import json
from pathlib import Path
import zlib

ROOT = Path(__file__).resolve().parent
REPO = ROOT.parents[1]
DEST = REPO / "docs/evidence/thor-f2fp-encoding-20261104/records.json"


def sha(data):
    return hashlib.sha256(data).hexdigest()


records, buffers, instructions, artifacts = [], [], [], []
for path in sorted(ROOT.rglob("*")):
    if not path.is_file() or path.name == "seal-result.json":
        continue
    blob = path.read_bytes()
    relative = path.relative_to(ROOT)
    item = {"path": str(relative), "bytes": len(blob), "sha256": sha(blob)}
    if path.suffix == ".cubin" or path.name == "probe":
        artifacts.append(item)
    elif relative.parts[0] == "decode":
        assert path.suffix == ".bin" and len(blob) == 16
        instructions.append({**item, "hex": blob.hex()})
    elif path.suffix == ".bin":
        buffers.append({**item, "encoding": "zlib+base64",
                        "data": base64.b64encode(zlib.compress(blob, 9)).decode()})
    else:
        assert path.suffix in (".py", ".cpp", ".ptx", ".json", ".jsonl", ".txt")
        records.append({**item, "text": blob.decode()})
bundle = {
    "schema": "q4t.thor_f2fp_encoding_evidence.v1",
    "scope": "bounded native F2FP format and scale encoding experiments; 29 candidates and 4 controls; not performance acceptance",
    "local_root": str(ROOT),
    "plan_sha256": sha((ROOT / "plan.json").read_bytes()),
    "records": records, "numerical_buffers": buffers,
    "offline_instruction_bytes": instructions, "local_artifacts": artifacts,
}
DEST.parent.mkdir(parents=True, exist_ok=True)
DEST.write_text(json.dumps(bundle, ensure_ascii=False, indent=2) + "\n")
sealed = json.loads(DEST.read_text())
for category in ("records", "numerical_buffers", "offline_instruction_bytes",
                 "local_artifacts"):
    for item in sealed[category]:
        local = (ROOT / item["path"]).read_bytes()
        if category == "records":
            data = item["text"].encode()
        elif category == "numerical_buffers":
            data = zlib.decompress(base64.b64decode(item["data"]))
        elif category == "offline_instruction_bytes":
            data = bytes.fromhex(item["hex"])
        else:
            data = local
        assert data == local and len(data) == item["bytes"] and sha(data) == item["sha256"]
summary = {"text_records": len(records), "numerical_buffers": len(buffers),
           "offline_instruction_bytes": len(instructions),
           "local_artifacts": len(artifacts), "bytes": DEST.stat().st_size,
           "sha256": sha(DEST.read_bytes()), "all_records_verified": True}
(ROOT / "seal-result.json").write_text(json.dumps(summary, indent=2) + "\n")
print(json.dumps(summary))

